let ptObject = JSON.parse(prayer_times);
let times = Object.values(ptObject.timings);

play_time = this_prayer_time;

let index = times.indexOf(this_prayer_time);

if (index === times.length - 1) {
    const json = JSON.parse(readFile("Tasker/database/Adhan Prayer Times/prayer_times.json"));
    const day = global('DAYM');

    if (day === json.length) {
        performTask('Update Prayer Details');
    } else {
        ptObject = json[day];
        times = Object.values(ptObject.timings);
        next_prayer_time = times[0];
    }
} else {
    next_prayer_time = times.find(time => time > this_prayer_time);
}

next_prayer = Object.entries(ptObject.timings)
    .find(([, value]) => value === next_prayer_time)?.[0];

prayer_times = JSON.stringify(ptObject, null, 4);

let jsonObject = JSON.parse(json);

var picked_date = jsonObject.data.date.readable;

var picked_date_hijri = `${jsonObject.data.date.hijri.day} ${jsonObject.data.date.hijri.month.en} ${jsonObject.data.date.hijri.year}`;

var list = [];

jsonObject.data.timings = Object.entries(jsonObject.data.timings).sort((a, b) => {
    const [hoursA, minutesA] = a[1].split(':').map(Number);
    const [hoursB, minutesB] = b[1].split(':').map(Number);
    const timeA = hoursA * 60 + minutesA;
    const timeB = hoursB * 60 + minutesB;
    return timeA - timeB;
});

jsonObject.data.timings = Object.fromEntries(jsonObject.data.timings);

for (let key in jsonObject.data.timings) {
    if
(jsonObject.data.timings.hasOwnProperty(key)) {
        let time = jsonObject.data.timings[key];
        list.push(`${key}: ${time}`);
    }
}

list = list.join(',');

let jsonObject = JSON.parse(json).data.map(item => ({
    date: {
        readable: item.date.readable,
        hijri: `${item.date.hijri.day} ${item.date.hijri.month.en} ${item.date.hijri.year}`
    },
    timings: Object.fromEntries(
        Object.entries(item.timings)
            .filter(([key]) => !["Firstthird", "Midnight", "Lastthird", "Imsak", "Sunrise", "Sunset"].includes(key))
            .map(([key, value]) => [key, value.replace(/ \(.+\)/, '').replace(/:/g, '.')])
    )
}));

if (day_offset == 0) {
    prayer_times = jsonObject[global('DAYM') - 1];
    let times = Object.values(prayer_times.timings);

    next_prayer_time = times.find(time => time > global('TIME'));

    if (!next_prayer_time) {
        let now = new Date();
        let nextMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0);
        let last_day = nextMonth.getDate();

        if (global('DAYM') == last_day) {
            if (now.getMonth() == 11) {
                let nextYear = new Date(now.getFullYear() + 1, 0, 1);
                prayer_times = jsonObject.find(item => item.date.readable === nextYear.toISOString().split('T')[0]);
                day_offset = 0;
            } else {
                day_offset = 1;
            }
        } else {
            prayer_times = jsonObject[global('DAYM')];
            times = Object.values(prayer_times.timings);
            next_prayer_time = times[0];
        }
    }
} else {
    prayer_times = jsonObject[0];
    times = Object.values(prayer_times.timings);
    next_prayer_time = times[0];
    day_offset = 0;
}

this_prayer_time = next_prayer_time;
this_prayer = Object.entries(prayer_times.timings).find(([, value]) => value === this_prayer_time)?.[0];

writeFile("Tasker/database/Adhan Prayer Times/prayer_times.json", JSON.stringify(jsonObject), 0);
prayer_times = JSON.stringify(prayer_times, null, 4);

const widgetObject = JSON.parse(widget);
const layout = local('par1');
const target = widgetObject[layout];

['background','icon_bg','fajr_bg','dhuhr_bg','asr_bg','maghrib_bg','isha_bg','text_primary','text_secondary'].forEach(field => {
  if (typeof window[field] === "string" && !window[field].startsWith("%")) {
    target.colors[field] = window[field];
  }
});

['font_family','corner_radius','icon_size','text_size_title','text_size_primary','text_size_secondary','show_checkbox'].forEach(field => {
  if (typeof window[field] === "string" && !window[field].startsWith("%")) {
    target[field] = window[field];
  }
});

['fajr','dhuhr','asr','maghrib','isha'].forEach(field => {
  if (typeof window[field] === "string" && !window[field].startsWith("%")) {
    target.icons[field] = window[field];
  }
});

widget = JSON.stringify(widgetObject, null, 4);

const widgetObject = JSON.parse(widget);
var all = Object.keys(widgetObject).join(',');
var enabled = Object.keys(widgetObject)
                         .filter(key => widgetObject[key].state === 'enabled')
                         .join(',');
widget = JSON.stringify(widgetObject, null, 4);

const widgetObject = JSON.parse(widget);
for (let key in widgetObject) {
  widgetObject[key].state = selected.includes(key) ? "enabled" : "disabled";
}
widget = JSON.stringify(widgetObject, null, 4);
